create or replace function public.guard_exercise_substitution_version() returns trigger language plpgsql security invoker set search_path = '' as $$ begin if new.updated_at < old.updated_at or (new.updated_at = old.updated_at and new.replacement is distinct from old.replacement) then return old; end if; return new; end; $$; revoke execute on function public.guard_exercise_substitution_version() from public, anon, authenticated; create trigger guard_exercise_substitution_version before update on public.exercise_substitutions for each row execute function public.guard_exercise_substitution_version();
